INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'格罗方德','GFS.US','semiconductor','fab',true,null,2630,null,67.91,null,'{"name":"格罗方德","code":"GFS.US","industry":"semiconductor","seg":"fab","market":"US","listed":true,"cap":2630,"rev":67.91,"pe":30,"gross":28.3,"revGrowth":6,"desc":"GlobalFoundries Inc.（格罗方德，中文亦称格芯），2009 年 3 月由 AMD 制造部门分拆、与阿联酋穆巴达拉（Mubadala）投资公司合资成立，总部美国纽约州马耳他（Malta, NY），注册地开曼群岛；2021 年 10 月在纳斯达克 IPO（代码 GFS，发行价 47 美元、募资约 26 亿美元），穆巴达拉仍持股约 82%。全球第三大晶圆代工厂，也是唯一同时在新加坡、欧盟和美国拥有晶圆厂的代工企业——新加坡 1 座 200mm＋1 座 300mm、德国德累斯顿 1 座 300mm、美国佛蒙特州 Essex Junction 1 座 200mm（该州最大私营雇主）、纽约州马耳他 1 座 300mm，员工约 1.4 万人，并为美国政府认证的 Trusted Foundry。2018 年主动放弃 7nm 以下先进制程，转向差异化特色工艺平台：FDX™（FD-SOI，含 22FDX）、RF-SOI（全球领先）、Fotonix 12 英寸硅光（支持 1.6T/3.2T CPO）、SiGe（硅锗，支持 200G/lane 光互连）、BCD、GaN 与集成电感。财务：2025 年营收 67.91 亿美元、营业利润 7.97 亿美元、净利 8.88 亿美元、总资产 171.41 亿美元、净资产 119.83 亿美元；2026 Q2 营收 17.86 亿美元（同比 +6%、环比 +9%），毛利率 28.3%（Non-IFRS 29.9%），净利 1.67 亿美元，晶圆出货 62.5 万片（300mm 等效），期末现金约 33 亿美元；Q3 指引营收 18.85 亿美元。分业务（2026 Q1）：汽车 3.82 亿美元（+24%）、通信基础设施与数据中心 2.30 亿美元（+32%）、技术服务 2.09 亿美元（+11%）、智能移动设备 5.58 亿美元（-5%）、家居与工业 IoT 2.55 亿美元（-22%）。2026-07 派发公司史上首次季度分红（0.12 美元/股）。并购与生态：2025-11 收购新加坡硅光代工厂 AMF（Advanced Micro Foundry），成为全球最大纯硅光代工厂（按营收）；近年陆续收购 Tagore Technology、MIPS、Synopsys 的 ARC 处理器 IP 业务（2026-06）、Photeon 的 IVR 业务（2026-07）。2026-09 与 Marvell 扩大多年 SiGe 产能协议（支持可插拔光模块、NPO、CPO），并与 SMART Photonics 合作推出硅光＋磷化铟（InP）开放代工。获美国商务部 3 亿美元（加速美国硅光领导地位）与 3.75 亿美元（量子技术方案 QTS）两项奖励意向书；2025-10 计划投资 11 亿欧元扩产、目标 2028 年年产能百万片，获欧盟芯片法案支持；2025-12 获德国政府经欧盟批准的 6.23 亿欧元援助。硅光业务目标 2026 年收入翻倍、2028 年退出时 run rate 超 10 亿美元。中国布局：北京、上海设研发中心，与增芯科技合作车用 CMOS；2024 年因未经授权向中芯国际关联公司供货被美国罚款 50 万美元。","latestTech":"FDX™（FD-SOI）平台与 RF-SOI 全球领先；Fotonix 12 英寸硅光平台支持 1.6T/3.2T CPO；SiGe 技术支持 200G/lane 光互连；已放弃 7nm 以下先进制程，专注差异化特色工艺。新加坡厂 2026 年 9 月产能利用率超 90%（据 DIGITIMES），设备交期成为扩产约束。","tech":[{"date":"2026-09","title":"与 Marvell 扩大多年 SiGe 产能协议，并与 SMART Photonics 合作硅光+InP 开放代工","kind":"技术","desc":"SiGe 产能扩产落地伯灵顿厂，支持 AI 基础设施用的可插拔光模块、近封装光学（NPO）与共封装光学（CPO）；与 SMART Photonics 组合硅光与磷化铟 PIC，拓展激光器与调制器等有源光学功能。"},{"date":"2026-07","title":"获美国商务部 3 亿美元奖励意向书加速美国硅光，完成收购 Photeon IVR 业务","kind":"政策","desc":"商务部下设 CHIPS 研发办公室拟拨款 3 亿美元推进下一代光学材料、晶圆技术与先进封装；Photeon 的集成稳压器（IVR）业务补充其 BCD、GaN 与集成电感技术，强化 AI 数据中心供电方案。"},{"date":"2026-06","title":"完成收购 Synopsys ARC 处理器 IP 业务","kind":"并购","desc":"连同此前收购的 MIPS，整合 RISC-V 处理器 IP、软件工具、定制设计与先进制造能力，构建 software-to-silicon 平台。"},{"date":"2026-05","title":"推出量子技术方案（QTS）","kind":"技术","desc":"基于十余年低温 CMOS、先进封装与材料科学投入，预计获美国商务部 3.75 亿美元拨款支持，规模化制造量子计算硬件。"},{"date":"2025-11","title":"收购新加坡硅光代工厂 AMF，成为全球最大纯硅光代工厂","kind":"并购","desc":"整合 AMF 的 200mm 硅光平台并规划向 300mm 迁移，承接美国 300mm 硅光能力转移至新加坡。"},{"date":"2018","title":"推出 FDX™ FD-SOI 平台，成为全球领先 RF-SOI 代工厂，并放弃 7nm 以下先进制程","kind":"战略","desc":"战略转向差异化、面向能效与连接性的特色工艺，此后专注 FD-SOI、射频、电源、硅光与车规。"}],"funding":[],"investorsStructured":[],"executives":[{"name":"Tim Breen","title":"首席执行官（CEO）","role":"management","bio":"2025 年出任 GlobalFoundries CEO，主导公司向硅光、SiGe 与电源等高增长差异化平台的战略聚焦，强调 AI 数据中心光互连为核心增长驱动。"},{"name":"Thomas Caulfield","title":"董事长","role":"board","bio":"GlobalFoundries 董事长，前任 CEO，主导公司放弃 7nm 以下先进制程、转向特色工艺平台及 2021 年纳斯达克 IPO 的战略转型。"},{"name":"Sam Franklin","title":"首席财务官（CFO）","role":"management","bio":"2025 年 12 月获任命为 CFO，负责资本开支纪律与利润率提升，投资优先投向硅光、FDX 与高性能 SiGe 等客户需求旺盛领域。"},{"name":"Gregg Bartlett","title":"首席技术官（CTO）","role":"management","bio":"GlobalFoundries CTO，负责差异化技术组合的研发与落地，主导技术在下一代市场的持续布局。"}],"spark":[2100,2300,2500,2630],"note":"特色工艺代工代表：与联电、世界先进、力积电、高塔半导体同梯队，但在硅光与 SiGe 上布局最深，是 AI 数据中心光互连的关键代工环节。国产对标华虹公司、中芯国际、三安光电：中国在特色工艺代工规模与成熟度上有差距，在 GaN/SiC 化合物代工处于追赶期；硅光代工环节国内由赛微电子（CompoundTek 授权）、中芯国际等推进，工艺代际落后于 GF 的 Fotonix 平台。"}'::jsonb,now()
)
